const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Cambodia';
  const aoi = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('ADM0_NAME', countryName)).geometry();

  // 2. Data Acquisition
  // Using the Hansen Global Forest Change dataset. It's a single global image, not a collection.
  // v1.10 covers up to year 2022.
  const hansen = ee.Image('UMD/hansen/global_forest_change_2022_v1_10');

  // 3. Processing
  // Select the 'lossyear' band. Values 1-22 correspond to years 2001-2022.
  const lossYear = hansen.select('lossyear');

  // Create a mask for forest loss within the specified period (2001-2014).
  // This corresponds to lossyear values from 1 to 14.
  const lossInPeriod = lossYear.gte(1).and(lossYear.lte(14));

  // Get the pixel area image.
  const pixelArea = ee.Image.pixelArea();

  // Calculate the area of loss in square kilometers.
  const lossArea = lossInPeriod.multiply(pixelArea).divide(1000000); // m^2 to km^2

  // 4. Calculation
  // Reduce the region to get the total loss area.
  // Using a larger scale (5000m) for a country-level statistic to avoid timeout.
  const scale = 5000;
  const stats = lossArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e10
  });

  try {
    const lossAreaSqKm = stats.get('lossyear').getInfo();

    // 5. Validation & Final Answer
    if (lossAreaSqKm === null || typeof lossAreaSqKm === 'undefined') {
        console.log("Calculation failed: Result is null.");
        console.log("C3");
        return;
    }

    console.log(`Country: ${countryName}`);
    console.log(`Period: 2001-2014`);
    console.log(`Total Forest Loss Area (2001-2014): ${lossAreaSqKm.toFixed(2)} sq km`);

    if (lossAreaSqKm > 0) {
        console.log("Evidence: A non-zero forest loss area was detected.");
        console.log("A");
    } else {
        // This case would mean exactly 0 sq km of loss was detected.
        console.log("Evidence: Zero forest loss area was detected.");
        console.log("B");
    }
  } catch(e) {
      console.log(`An error occurred during the analysis: ${e}`);
      console.log("D");
  }

}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
